/* ---------- scenarios ---------- */
var S=[
 {id:"start",name:"Start the program",sum:"From double-click to every plugin running, and what happens when a check fails.",
  steps:[
   {t:"You launch hetu",n:["human","boot"],e:["human_boot"],x:"The boot loader runs first. It is the one part that can't be a plugin and it holds no policy of its own.",c:["Boot loader comes from the read-only install"],th:[]},
   {t:"Read the security state",n:["boot","bundle","service"],e:["boot_bundle"],x:"The security state lists every plugin hash, pinned signer, grant, class and switch. It sits in a folder only hetu's service can write, so nothing running as you can have edited, replayed or deleted it. The boot loader parses it with the strict schema.",c:["Only the service writes it","Duplicate keys and unknown types rejected"],th:[24,25,54]},
   {t:"Load the host, editor and guards",n:["boot","firstparty","loader"],e:["boot_first","first_loader"],x:"First-party core plugins come only from the read-only install, never from the plugin folder. The plugin loader sets up each plugin's environment, and the host starts as the running guard.",c:["Program Files: a normal program can't edit these files"],th:[49]},
   {t:"Check every plugin file",n:["loader","pfolder"],e:["loader_pfolder"],x:"The loader hashes every file of every plugin and compares with the security state. It then loads the exact bytes it hashed, so nothing can be swapped in between.",c:["contentHash matches","Load hashed bytes, never re-read the path"],th:[24,26]},
   {t:"Start guards, then everything else",n:["loader","leases","mcp","gitp","search","watchp","community"],e:["loader_hidden"],x:"Always-on plugins start as workers in the hidden renderer, so they keep running with every window closed. Guards start first. Other plugins are held until the guards report ready.",c:["Guards first","Each worker gets exactly its approved grants"],th:[35]},
   {t:"Open the editor window",n:["loader","egate","ecore","eplug","frames"],e:["loader_egate"],x:"If you open a window, the editor mount asks the daemon what to load and with which grants. The editor core plugin runs in the page, editor plugins in workers and frames.",c:["The window can't touch disk, only the daemon can"],th:[42]},
   {t:"Record the start",n:["gate","logw","logs"],e:["gate_log","logw_logs"],x:"\"State N loaded\" goes into the hash-chained event log. With the optional cloud plugin, a copy leaves the machine.",c:["Hash chain"],th:[11]},
   {t:"If any check failed",n:["loader","hetuui","firstparty"],e:["loader_ui","boot_first"],x:"A failed check never means a silent start. Every guard stays on, the suspect parts stay off, first-party pieces can be restored from the read-only install, and hetu tells you exactly what changed.",c:["Fail closed","Banner in hetu's trusted UI"],th:[39],bad:true}
  ]},
 {id:"install",name:"Install a plugin",sum:"From a developer's release to the plugin up and running on your machine.",
  steps:[
   {t:"Developer signs a release",n:["dev","internet"],e:["dev_internet"],x:"The developer's GitHub workflow signs the release keylessly with Sigstore. The signature lands in Rekor, the public append-only log. The signer identity is the repo plus workflow.",c:["No long-lived key to steal"],th:[48]},
   {t:"You add it to the plugin folder",n:["human","internet","pfolder"],e:["internet_pfolder","human_pfolder"],x:"You download the package with its signature file into the one central plugin folder. Nothing loads yet.",c:["A file in the folder is not an approval"],th:[]},
   {t:"hetu notices a new plugin",n:["loader","pfolder","hetuui"],e:["loader_pfolder","loader_ui"],x:"The loader sees a plugin that isn't in the security state. It never loads it silently. An agent dropping a plugin in hits the same prompt.",c:["New plugin found: prompt"],th:[27]},
   {t:"Verify and classify",n:["loader","pfolder"],e:["loader_pfolder"],x:"The loader verifies the Sigstore signature locally, reads the manifest with the strict schema and computes the class from what it requests. Read plus network together ranks class 4.",c:["Signature valid","Class computed, never declared","Combination rules"],th:[27,54]},
   {t:"See exactly what it asks for",n:["hetuui"],e:[],x:"hetu's own window shows the plugin, its signer identity, its class and every permission. Approval is all or nothing: plugin makers own their permission design.",c:["All or nothing","Signer shown"],th:[33]},
   {t:"Approve with your gesture",n:["human","hetuui","gate","signer"],e:["human_ui","ui_gate","gate_signer"],x:"You confirm in hetu's trusted window, which names what is being changed and sends the confirmation through the gate. The backend then starts Windows Hello or Touch ID.",c:["Only Confirm in the trusted window starts the prompt"],th:[43,33]},
   {t:"The service checks your gesture",n:["signer","keystore","service"],e:["signer_key","signer_service"],x:"The Hello client gets a one-time code from hetu's service for this exact change. Windows Hello signs the code and the change, and the service checks the signature against the key it enrolled.",c:["Code tied to the change","Enrolled key only"],th:[43,52]},
   {t:"The service writes the state",n:["service","bundle"],e:["service_bundle"],x:"The security state now records the plugin's version, content hash, pinned signer, granted permissions and class. Later updates must come from the same signer.",c:["Signer pinned (trust on first use)","Only the service writes"],th:[47]},
   {t:"Start the plugin",n:["loader","community","eplug"],e:["loader_hidden","loader_egate"],x:"The loader starts the plugin's daemon half in the hidden renderer and its editor half in the window, each as a worker with exactly the approved grants.",c:["Worker sandbox","Grants from the security state"],th:[29]},
   {t:"Its first request",n:["community","gate","logw"],e:["hidden_gate","gate_log"],x:"Every action the plugin takes is a capability call the gate checks and logs. It has no power of its own.",c:["Reference monitor"],th:[30,31]}
  ]},
 {id:"update",name:"A plugin update arrives",sum:"Which updates load on their own, which ask you, and when hetu warns.",
  steps:[
   {t:"A new version appears",n:["dev","internet","pfolder"],e:["dev_internet","internet_pfolder"],x:"The developer publishes a new signed release and it lands in your plugin folder.",c:[],th:[]},
   {t:"Same signer?",n:["loader","pfolder","bundle"],e:["loader_pfolder"],x:"The loader compares the signer identity with the one pinned at first approval. A different identity, even with a valid signature, is treated as a new plugin with a warning. That stops a forked plugin with a backdoor.",c:["Signer must match the pin"],th:[47]},
   {t:"Did it ask for more?",n:["loader","hetuui"],e:["loader_ui"],x:"An update whose manifest requests anything more needs your approval again, whatever its class.",c:["Widened manifest asks again"],th:[28]},
   {t:"Class 0 loads on its own",n:["loader","community"],e:["loader_hidden"],x:"Only plugins with no privilege (class 0) update without a prompt. Everything else asks every time, which bounds a hijacked developer workflow.",c:["Only class 0 auto-updates"],th:[48]},
   {t:"Everything else asks you",n:["human","hetuui","gate","signer","keystore","service","bundle"],e:["human_ui","ui_gate","gate_signer","signer_key","signer_service","service_bundle"],x:"For class 1 and up you approve the update with your gesture, and the service writes it into the security state.",c:["Your gesture per approval"],th:[43]},
   {t:"First-party never comes this way",n:["firstparty","boot"],e:["boot_first"],x:"The host, editor and guards update only with the app install itself, never through the plugin channel.",c:["Core ships inside the app install"],th:[49]}
  ]},
 {id:"agent",name:"An agent edits a note",sum:"First connection, consent, lease, edit, commit and the events that follow.",
  steps:[
   {t:"First call without a token",n:["agent","http"],e:["agent_http"],x:"The agent calls hetu's MCP endpoint on 127.0.0.1. With no token it gets a 401 and the Protected Resource Metadata pointing at hetu's authorization server.",c:["Loopback only, Host and Origin checks"],th:[14,15]},
   {t:"OAuth with PKCE",n:["agent","oauth","internet"],e:["agent_oauth","oauth_internet"],x:"The agent starts OAuth 2.1 with PKCE. If it identifies with a client metadata URL, hetu fetches it over HTTPS only and never from private or loopback addresses.",c:["HTTPS only","No private addresses"],th:[51]},
   {t:"You consent once",n:["oauth","hetuui","human","gate","signer","keystore","service","bundle"],e:["oauth_ui","human_ui","ui_gate","gate_signer","signer_key","signer_service","service_bundle"],x:"hetu's consent page shows the agent and lets you set its grants. Your gesture approves it and the service writes the agent's grants into the security state.",c:["Agent grants need your gesture"],th:[9]},
   {t:"Short-lived token",n:["oauth","agent"],e:["agent_oauth"],x:"The agent receives a short-lived access token bound to hetu. Its harness stores it, not hetu. Refresh tokens rotate, and reuse of an old one revokes the chain and alerts you.",c:["Short-lived","Reuse detection"],th:[50]},
   {t:"Ask for a lease",n:["agent","http","mcp","gate","leases"],e:["agent_http","http_mcp","hidden_gate"],x:"The MCP plugin forwards acquire_lease with the agent's identity. The gate checks the agent's grants and the MCP plugin's together, and the leases guard decides.",c:["Agent grants and MCP grants both"],th:[40,1]},
   {t:"Refused? Only its own details",n:["leases","mcp"],e:[],x:"If another writer holds the note, the refusal carries path, holder and expiry only. Never another agent's lease id. That's the A-05 lesson.",c:["Refusal names only the caller's things"],th:[6,37]},
   {t:"Edit the note",n:["mcp","gate","write","leases","vault"],e:["hidden_gate","gate_write","leases_write","write_vault"],x:"edit_note goes through the gate to the single write path. The version check stops a stale write, the lease guard confirms the holder, the file is written.",c:["StaleVersion","Lease holder only"],th:[1]},
   {t:"Commit to the shadow repo",n:["gate","exec","osproc","shadow","vault"],e:["gate_exec","exec_proc","proc_shadow","proc_vault"],x:"The core runs git against the hetu-owned shadow repo with a clean environment. The commit is attributed to the agent. Your own repo is untouched.",c:["Clean environment","Vault git config never read"],th:[13,45]},
   {t:"Tell the others",n:["write","bus","search","egate"],e:["write_bus","bus_hidden","bus_egate"],x:"note.written goes to subscribers whose read scope covers the note: the search indexer and an open editor. A signal and the path, never the content.",c:["Scope filter"],th:[37]},
   {t:"Everything was logged",n:["gate","logw","logs"],e:["gate_log","logw_logs"],x:"Each step above is in the event log with the agent's identity.",c:["Hash chain"],th:[11]}
  ]},
 {id:"type",name:"You type, a plugin decorates",sum:"The editor core, the bridge, edits from a plugin and saving as you.",
  steps:[
   {t:"You type",n:["human","ecore"],e:["human_ecore"],x:"Keystrokes go straight to the editor core. Hidden marks re-hide markdown markers instantly because they run inside the page, one of only two in-page features.",c:["Hidden marks in-page"],th:[]},
   {t:"Plugins hear about it",n:["ecore","egate","eplug"],e:["egate_ecore"],x:"The editor bridge tells subscribed editor plugins the document changed, within their read scope.",c:["Scope filter"],th:[37]},
   {t:"A plugin sends decorations",n:["eplug","egate","ecore"],e:["eplug_egate","egate_ecore"],x:"A search-highlight plugin sends CodeMirror-shaped decoration specs. The bridge checks ranges, allows theme styles only and accepts widgets only as text or a frame.",c:["Theme styles only","No HTML widgets"],th:[41,19]},
   {t:"A plugin sends an edit",n:["eplug","egate","ecore"],e:["eplug_egate","egate_ecore"],x:"A table formatter sends a change list against document version N. If you typed since, the version is stale and the edit is rejected. Accepted edits are attributed to the plugin.",c:["Version check","Attributed to the plugin"],th:[41]},
   {t:"Save as you",n:["ecore","gate","write","vault"],e:["ecore_gate","gate_write","write_vault"],x:"The editor saves over Electron IPC, through the same gate as every other call. The daemon writes the file and records the edit as yours.",c:["Attributed to you"],th:[19,42]},
   {t:"Raw view tells the truth",n:["human","ecore"],e:["human_ecore"],x:"Ctrl+/ switches to the raw view, which ignores every plugin decoration. A decoration can never hide text from you there.",c:["Raw view in-page, unreachable by plugins"],th:[8]}
  ]},
 {id:"guardoff",name:"Switch a guard off",sum:"How you switch security off on purpose, and why nothing else can.",
  steps:[
   {t:"You choose to switch it off",n:["human","hetuui"],e:["human_ui"],x:"Any hetu window can ask for the switch, and only the trusted window can confirm it. MCP and plugins can't reach it.",c:["Never over MCP, never by a plugin"],th:[22]},
   {t:"Your gesture approves it",n:["hetuui","gate","signer","keystore","service"],e:["ui_gate","gate_signer","signer_key","signer_service"],x:"The trusted window sends your confirmation through the gate and the backend starts the prompt. Windows Hello or Touch ID signs a one-time code from the service together with the change, and the service checks it.",c:["Code tied to the change"],th:[43]},
   {t:"New state with the switch",n:["service","bundle"],e:["service_bundle"],x:"The service writes the switch into the per-machine security state, never into the vault, so a synced or cloned vault can't bring it along.",c:["Per machine","Only the service writes"],th:[22]},
   {t:"A banner while it's off",n:["loader","hetuui","logw","logs"],e:["loader_ui","gate_log","logw_logs"],x:"While any guard is off hetu says so plainly, and the log records who switched it.",c:["Visible state","Logged"],th:[11]},
   {t:"Crash is not a switch",n:["leases","write"],e:["leases_write"],x:"If a guard is missing or crashed without you switching it off, writes fail closed.",c:["Fail closed"],th:[39],bad:true}
  ]},
 {id:"replay",name:"Shell agent goes after security",sum:"An agent with a shell tries to change hetu's security state without you. What stops it and what's left.",
  steps:[
   {t:"It edits or restores the state",n:["shell","bundle"],e:["shell_bundle"],x:"The agent tries to edit the security state, or copy an old one with a guard off over it, or delete it so hetu starts fresh. The folder belongs to hetu's service and a program running as you can't write it.",c:["Only the service writes the folder"],th:[24,25,55]},
   {t:"It goes after the service",n:["shell","service"],e:["shell_service"],x:"The service runs under its own Windows account in session 0. A program running as you can't open it, write its memory or hook it, since it has no window on your desktop.",c:["A different account","No window to hook"],th:[56]},
   {t:"It makes its own key",n:["shell","keystore"],e:["shell_key"],x:"On Windows it can delete your Hello key or make a new one under hetu's name, with no gesture. The service only trusts the key it enrolled, so a new key signs nothing that counts. A deleted key blocks changes and forces a recovery, see Enroll or recover your key.",c:["Enrolled key only","Fails closed"],th:[43,53,61]},
   {t:"It tries to fool you instead",n:["shell","hetuui","human"],e:["shell_ui"],x:"What's left is deception. With code injected into hetu it could show you one change in the trusted window and ask for another. It still needs your real gesture, and the request is logged. hetu accepts this risk: no app on one PC can show you something an injected program can't also draw.",c:["Needs your gesture","Accepted risk"],th:[58],bad:true},
   {t:"Every attempt is on record",n:["service"],e:[],x:"The service logs every request and refusal in its own folder, where a program running as you can't edit them.",c:["Logged out of reach"],th:[11]}
  ]},
 {id:"enroll",name:"Enroll or recover your key",sum:"How the service learns which key to trust at first install and after a lost key and where that is weakest.",
  steps:[
   {t:"The helper starts",n:["human","enroll"],e:["human_enroll"],x:"The installer runs it last. After a lost key hetu tells you to run it from Start. It shows the Windows elevation prompt (UAC) and takes no arguments or paths. On a standard account or with Administrator protection, where elevating means running as another account, it refuses and says so. At first install every guard is on with no community plugins. Until a key is enrolled notes work and security changes are refused.",c:["Elevated","No arguments or paths"],th:[61]},
   {t:"It makes the key itself",n:["enroll","keystore"],e:["enroll_keystore"],x:"One gesture makes a new Hello key under a random name. The key isn't made by a program running as you and passed in, since that program could pass in its own.",c:["Made by the elevated helper","One gesture"],th:[43,60]},
   {t:"An agent tries to swap it",n:["shell","keystore","enroll"],e:["shell_key","enroll_keystore"],x:"A program running as you can list the new key's name, delete the key and plant its own under that name with no gesture. The helper's own Hello object then hands back the planted key's public half. So the helper opens the key once and reads two things from that one open key: its public half and a marker Windows sets on how the key was made. A different public key or the wrong marker is refused before any signature is asked for. Microsoft doesn't document that marker. It was read on one PC and one Windows build and a planted key that reads the right marker hasn't been tested yet. A build that changes it stops enrollment until hetu is updated.",c:["Marker checked","Right-marker plant not tested"],th:[60],bad:true},
   {t:"The service takes the key",n:["enroll","service","bundle"],e:["enroll_service","service_bundle"],x:"The helper signs a one-time code with the key and sends the public half over a named pipe only elevated programs can open. The service checks the signature, replaces the old key in one write and logs it. A signed change can't do this. If it could, one fooled gesture could swap in a key that never asks you again. This way it costs one change.",c:["Elevated pipe","Logged"],th:[60]},
   {t:"A lost key blocks changes",n:["shell","keystore","bundle"],e:["shell_key"],x:"A program running as you can delete your key with no gesture. Your security state stays as it was and every change is refused until you run the helper again. That includes tightening a setting or removing a plugin's grant. If Administrator protection was turned on after you enrolled, the helper refuses, so the lock lasts until it is turned off. hetu checks the key at start and warns if it is missing or different. Code injected into hetu can hide that warning but not the service's log.",c:["Fails closed","State unchanged"],th:[39,43,55],bad:true},
   {t:"An agent fakes the recovery",n:["shell","human"],e:["shell_fake"],x:"So an attacker can choose when recovery happens. It can delete your key, then raise a UAC prompt for its own program while you expect hetu's. hetu has no paid signing, so its real prompt also shows an unknown publisher. It could also start the real helper itself in a way that lets it take the helper over. If you approve either prompt, its code runs elevated and can enroll a key of its own. hetu accepts this risk: recovery should be rare unless someone is targeting you. It is the same exposure as updating hetu.",c:["Accepted risk"],th:[57,61],bad:true},
   {t:"First install has the same weak moment",n:["shell","human","enroll"],e:[],x:"A program already running as you can change the downloaded installer or plant files beside it before you run it. If you approve that prompt, its code runs elevated. The published hashes only help if you check them and the file doesn't change afterwards. hetu accepts this risk too.",c:["Accepted risk"],th:[38,57,62],bad:true},
   {t:"A program that can elevate",n:["shell","enroll","service"],e:[],x:"A program that can elevate can enroll its own key. It could also replace the service, so enrollment adds no new loss. That doesn't always take a prompt: public UAC bypasses reach elevation with no prompt on an admin account at default settings. A PC set to elevate without asking offers even less. A targeted program can get there without waiting for install or recovery. hetu treats elevated programs as out of scope and says so when UAC is set to elevate without asking.",c:["Out of scope"],th:[57],bad:true}
  ]},
 {id:"hang",name:"A plugin hangs",sum:"The watchdog: the kernel measures and stops, the plugin decides, you choose.",
  steps:[
   {t:"Heartbeat goes unanswered",n:["watchm","community"],e:["watchm_hidden"],x:"The host pings each worker and reads per-process metrics. One plugin stops answering or its memory keeps climbing.",c:["Heartbeat","Per-process metrics"],th:[36]},
   {t:"Stall it",n:["watchm","community","gate"],e:["watchm_hidden"],x:"Workers can't be paused, so the host stops answering the plugin's bridge calls. It can't touch anything while you decide. A busy loop still burns CPU until terminated.",c:["Stop serving its calls"],th:[36]},
   {t:"The watchdog plugin decides",n:["watchp","watchm"],e:["watchp_watchm"],x:"The policy half labels it by behavior, such as \"memory consuming\", since nobody can tell malicious from badly written from outside.",c:["Label by behavior"],th:[36]},
   {t:"You choose",n:["watchm","hetuui","human"],e:["watchm_ui","human_ui"],x:"hetu asks whether it should keep running. Stop means terminate and restart with backoff, or disable.",c:["You decide"],th:[36]},
   {t:"Terminate",n:["watchm","community","logw"],e:["watchm_hidden","gate_log"],x:"The host terminates the worker. The event is logged.",c:["worker.terminate()"],th:[36]}
  ]},
 {id:"writerun",name:"Plugin tries write-then-run",sum:"A malicious plugin with an exec grant tries to run code it wrote itself.",
  steps:[
   {t:"It writes a script into its storage",n:["community","gate","pfolder"],e:["hidden_gate","gate_pfolder"],x:"storage is always granted, so writing helper.js into its own space succeeds.",c:["Own space only"],th:[46],bad:true},
   {t:"It asks to run it",n:["community","gate","exec"],e:["hidden_gate","gate_exec"],x:"Its manifest claimed the exact command node <storage>/helper.js, and the string matches exactly.",c:["Exact match passes"],th:[46],bad:true},
   {t:"Refused",n:["exec","logw"],e:["gate_log"],x:"The exec runner refuses any command that runs a file from storage or the vault as code. Files run as code must come from the signed package or the system. The refusal is logged.",c:["Only signed package or system files run as code"],th:[46]},
   {t:"Even a clean command is pinned",n:["exec","osproc"],e:["exec_proc"],x:"Allowed commands run with an environment the core builds: absolute paths, fixed working directory, no NODE_OPTIONS or similar.",c:["Clean environment"],th:[45]}
  ]},
 {id:"direct",name:"Shell agent edits a note directly",sum:"An agent writes a note on disk, going around hetu.",
  steps:[
   {t:"It writes the file",n:["shell","vault"],e:["shell_vault"],x:"An agent with a shell edits a note directly, bypassing leases and the write path.",c:[],th:[10],bad:true},
   {t:"The watcher sees it",n:["watcher","vault","logw"],e:["watcher_vault","watcher_logw"],x:"The disk watcher compares with the daemon's own writes and flags the outside write.",c:["Detection only"],th:[10]},
   {t:"Recorded as unknown",n:["gate","exec","osproc","shadow"],e:["gate_exec","exec_proc","proc_shadow"],x:"The next commit in the shadow repo marks the change as made by an unknown writer, never under an agent's name. History keeps the version before.",c:["Attribution","Revertable"],th:[10]},
   {t:"A held lease ends with a warning",n:["leases","hetuui"],e:["loader_ui"],x:"If an agent held a lease on that note, releasing it raises a warning, and the next write against the old version is rejected as stale.",c:["StaleVersion"],th:[10]}
  ]}
];
